import {utilityKinds,utilityExample} from './utility-generators.js';
import {labKinds,generateLab} from './field-lab-generators.js';
const f=(name,code,where)=>({name,code:code.trim()+'\n',where});
export const extendedKinds=[...labKinds,...utilityKinds,
 ['f4-account','F4_ACCOUNT · G/L 계정 전체 묶음'],['f4-costcenter','F4_COSTCENTER · 코스트센터'],['f4-order','F4_ORDER · 내부오더'],['f4-wbs','F4_WBS · WBS'],['f4-dynpro','F4 · 사용자 DDIC 필드'],
 ['make-fcat','MAKE_FCAT · Grid + Custom Container'],['alv-toolbar','ALV · Toolbar / User command'],['alv-top','ALV · TOP_OF_PAGE + 문서 컨테이너'],['alv-edit','ALV · 편집 / DATA_CHANGED / 저장 전 검사'],['alv-hotspot','ALV · Hotspot / Double click'],
 ['list-top','클래식 리스트 · TOP-OF-PAGE'],['crud','DB · CREATE / READ / UPDATE / DELETE'],['db-create','DB · CREATE (INSERT)'],['db-update','DB · UPDATE'],['db-delete','DB · DELETE'],['itab-crud','내부테이블 · CRUD'],
 ['validation','입력 검증 · 필수 / 존재 / 범위'],['popup','Popup · 확인 후 처리'],['upload','파일 · 로컬 텍스트 업로드'],['download','파일 · 텍스트 다운로드'],['date','날짜 · 유효성 / 기간'],['amount','금액 · 통화별 외부 표시'],['alpha','변환 · ALPHA 입력 / 출력'],['join','Open SQL · JOIN 전체 조회'],['range','RANGES · 조건 구성'],['local-class','Local Class · FORM 연계'],['form','FORM / PERFORM · 타입 있는 인터페이스'],['function','Function Module · SE37 인터페이스'],['authority','권한 · AUTHORITY-CHECK'],['fi-check','FI · BAPI 전표 CHECK'],['shdb','FI · SHDB / BDC 연결 안내'],['lock','동시성 · Lock Object 안내']
];
export const isExtended=k=>extendedKinds.some(([id])=>id===k);
export function generateExtended(kind,o){
 const lab=generateLab(kind,o);if(lab)return lab;
 const p=o.program.toLowerCase(),s=o.screen,t=o.table.toLowerCase(),k=o.key.toLowerCase();
 const files=[]; const add=(n,c,w='SE38 · Include')=>files.push(f(n,c,w));
 const guide=(text)=>add('00_README.txt',`적용 환경: Standard ABAP / SAP GUI / ABAP 7.40 SP08 이상. ABAP Cloud용이 아닙니다.\n${text}\nSE11/SE37 인터페이스와 권한은 대상 시스템에서 확인하세요. SAP에서 컴파일·실행한 결과는 아닙니다.`, '적용 전제 · 만들 위치 · 점검 순서');
 const report=(top,events,forms)=>{add(p+'.abap',`REPORT ${p}.\nINCLUDE ${p}_top.\n${events}\nINCLUDE ${p}_f01.`,'SE38 · 실행 프로그램');add(p+'_top.abap',top);add(p+'_f01.abap',forms);};
 const util=utilityExample(kind,o); if(util){guide(util[0]);report(util[1],util[2],util[3]);return files;}
 if(kind.startsWith('f4-')) return dynproF4(kind,o);
 if(['make-fcat','alv-toolbar','alv-top','alv-edit','alv-hotspot'].includes(kind))return grid(kind,o);
 if(['crud','db-create','db-update','db-delete'].includes(kind))return crud(kind,o);
 switch(kind){
 case 'list-top':
 guide('리스트 출력용 TOP-OF-PAGE입니다. CL_GUI_ALV_GRID의 TOP_OF_PAGE 이벤트와 구분합니다. F8 실행 시 WRITE가 첫 페이지를 생성합니다.');
 report(`DATA gv_lines TYPE i.`, `TOP-OF-PAGE.\n  PERFORM top_of_page.\nSTART-OF-SELECTION.\n  PERFORM display_list.`, `FORM top_of_page.\n  WRITE: / '회사코드 목록', sy-datum, sy-uzeit, 'Page', sy-pagno.\n  ULINE.\nENDFORM.\nFORM display_list.\n  DATA lt_company TYPE STANDARD TABLE OF t001.\n  DATA ls_company TYPE t001.\n  SELECT * FROM t001 INTO TABLE lt_company.\n  LOOP AT lt_company INTO ls_company.\n    WRITE: / ls_company-bukrs, ls_company-butxt.\n  ENDLOOP.\n  gv_lines = lines( lt_company ).\n  WRITE: / '건수', gv_lines.\nENDFORM.`);break;
 case 'itab-crud':
 guide('DB 변경 없이 메모리 목록에서 CREATE/READ/UPDATE/DELETE를 실행합니다.');
 report(`TYPES: BEGIN OF ty_data, id TYPE i, text TYPE string, END OF ty_data.\nDATA: gt_data TYPE SORTED TABLE OF ty_data WITH UNIQUE KEY id,\n      gs_data TYPE ty_data.`, `START-OF-SELECTION.\n  PERFORM maintain_data.`, `FORM maintain_data.\n  gs_data-id = 1. gs_data-text = '처음'.\n  INSERT gs_data INTO TABLE gt_data.\n  IF sy-subrc <> 0.\n    MESSAGE '중복 키입니다.' TYPE 'I'.\n    RETURN.\n  ENDIF.\n  READ TABLE gt_data INTO gs_data WITH TABLE KEY id = 1.\n  IF sy-subrc = 0.\n    gs_data-text = '수정'.\n    MODIFY TABLE gt_data FROM gs_data.\n  ENDIF.\n  DELETE TABLE gt_data WITH TABLE KEY id = 1.\n  WRITE: / '남은 건수', lines( gt_data ).\nENDFORM.`);break;
 case 'popup':
 guide('확인값 1에서만 후속 처리를 합니다. 2 또는 A(취소)는 처리하지 않습니다.');
 report(`DATA gv_answer TYPE c LENGTH 1.`, `START-OF-SELECTION.\n  PERFORM confirm_action.`, `FORM confirm_action.\n  CALL FUNCTION 'POPUP_TO_CONFIRM'\n    EXPORTING titlebar = '확인' text_question = '계속하시겠습니까?'\n              text_button_1 = '예' text_button_2 = '아니오'\n              default_button = '2' display_cancel_button = 'X'\n    IMPORTING answer = gv_answer\n    EXCEPTIONS text_not_found = 1 OTHERS = 2.\n  IF sy-subrc <> 0 OR gv_answer <> '1'.\n    RETURN.\n  ENDIF.\n  WRITE / '확인되었습니다.'.\nENDFORM.`);break;
 case 'validation':
 guide('AT SELECTION-SCREEN에서 E 메시지로 실행을 차단합니다. START-OF-SELECTION의 S DISPLAY LIKE E는 실행을 차단하지 않습니다.');
 report(`PARAMETERS: pa_bukrs TYPE t001-bukrs OBLIGATORY,\n            pa_count TYPE i DEFAULT 10.`, `AT SELECTION-SCREEN.\n  PERFORM validate_input.\nSTART-OF-SELECTION.\n  WRITE / pa_bukrs.`, `FORM validate_input.\n  DATA lv_exists TYPE abap_bool.\n  IF pa_bukrs IS INITIAL.\n    MESSAGE '회사코드를 입력하세요.' TYPE 'E'.\n  ENDIF.\n  SELECT SINGLE @abap_true FROM t001\n    WHERE bukrs = @pa_bukrs INTO @lv_exists.\n  IF sy-subrc <> 0.\n    MESSAGE '회사코드가 존재하지 않습니다.' TYPE 'E'.\n  ENDIF.\n  IF pa_count < 1 OR pa_count > 10000.\n    MESSAGE '건수는 1~10000입니다.' TYPE 'E'.\n  ENDIF.\nENDFORM.`);break;
 case 'date':
 guide('DATS는 형식만으로 달력상 유효성을 보장하지 않습니다. 시작/종료일을 각각 검사하고 순서를 비교합니다.');
 report(`PARAMETERS: pa_from TYPE sy-datum DEFAULT sy-datum OBLIGATORY,\n            pa_to TYPE sy-datum DEFAULT sy-datum OBLIGATORY.`, `AT SELECTION-SCREEN.\n  PERFORM check_dates.\nSTART-OF-SELECTION.\n  WRITE: / pa_from, pa_to.`, `FORM check_dates.\n  CALL FUNCTION 'DATE_CHECK_PLAUSIBILITY'\n    EXPORTING date = pa_from\n    EXCEPTIONS plausibility_check_failed = 1 OTHERS = 2.\n  IF sy-subrc <> 0.\n    MESSAGE '시작일이 올바르지 않습니다.' TYPE 'E'.\n  ENDIF.\n  CALL FUNCTION 'DATE_CHECK_PLAUSIBILITY'\n    EXPORTING date = pa_to\n    EXCEPTIONS plausibility_check_failed = 1 OTHERS = 2.\n  IF sy-subrc <> 0 OR pa_from > pa_to.\n    MESSAGE '종료일과 기간을 확인하세요.' TYPE 'E'.\n  ENDIF.\nENDFORM.`);break;
 case 'amount':
 guide('내부 금액은 WRBTR 타입 기준입니다. 화면 표시 시 CURRENCY를 지정해 TCURX 소수 자릿수를 적용합니다. 외부 CSV 금액을 내부 금액으로 변환하는 코드가 아닙니다.');
 report(`PARAMETERS: pa_curr TYPE tcurc-waers DEFAULT 'KRW',\n            pa_amt TYPE bseg-wrbtr DEFAULT '100'.\nDATA gv_text TYPE c LENGTH 30.`, `AT SELECTION-SCREEN.\n  PERFORM check_currency.\nSTART-OF-SELECTION.\n  PERFORM format_amount.`, `FORM check_currency.\n  DATA lv_curr TYPE tcurc-waers.\n  SELECT SINGLE waers FROM tcurc INTO lv_curr WHERE waers = pa_curr.\n  IF sy-subrc <> 0.\n    MESSAGE '통화코드를 확인하세요.' TYPE 'E'.\n  ENDIF.\nENDFORM.\nFORM format_amount.\n  WRITE pa_amt TO gv_text CURRENCY pa_curr.\n  WRITE: / gv_text, pa_curr.\nENDFORM.`);break;
 case 'alpha':
 guide('ALPHA 도메인 필드용입니다. WBS POSID에는 ABPSP 변환을 사용하며 ALPHA를 임의 적용하지 않습니다.');
 report(`PARAMETERS pa_kunnr TYPE kna1-kunnr.\nDATA: gv_internal TYPE kna1-kunnr, gv_external TYPE kna1-kunnr.`, `START-OF-SELECTION.\n  PERFORM convert_key.`, `FORM convert_key.\n  CALL FUNCTION 'CONVERSION_EXIT_ALPHA_INPUT'\n    EXPORTING input = pa_kunnr IMPORTING output = gv_internal.\n  CALL FUNCTION 'CONVERSION_EXIT_ALPHA_OUTPUT'\n    EXPORTING input = gv_internal IMPORTING output = gv_external.\n  WRITE: / gv_internal, gv_external.\nENDFORM.`);break;
 case 'join':
 guide('T001과 T004T의 전체 키(언어 포함)로 LEFT JOIN합니다. 계정과목표 텍스트가 없어도 회사코드는 남습니다.');
 report(`TYPES: BEGIN OF ty_data, bukrs TYPE t001-bukrs, butxt TYPE t001-butxt,\n       ktopl TYPE t001-ktopl, ktplt TYPE t004t-ktplt, END OF ty_data.\nDATA: gt_data TYPE STANDARD TABLE OF ty_data, gs_data TYPE ty_data.\nPARAMETERS pa_bukrs TYPE t001-bukrs.`, `START-OF-SELECTION.\n  PERFORM get_data.\n  LOOP AT gt_data INTO gs_data.\n    WRITE: / gs_data-bukrs, gs_data-butxt, gs_data-ktplt.\n  ENDLOOP.`, `FORM get_data.\n  SELECT a~bukrs, a~butxt, a~ktopl, b~ktplt\n    FROM t001 AS a LEFT OUTER JOIN t004t AS b\n      ON b~ktopl = a~ktopl AND b~spras = @sy-langu\n    WHERE a~bukrs = @pa_bukrs\n    INTO TABLE @gt_data.\nENDFORM.`);break;
 case 'range':
 guide('RANGE가 비어 있으면 IN 조건은 전체를 허용합니다. 전체 조회를 막기 위해 필수값을 지정합니다.');
 report(`DATA gr_key TYPE RANGE OF ${t}-${k}.\nDATA gs_range LIKE LINE OF gr_key.\nDATA gt_data TYPE STANDARD TABLE OF ${t}.\nPARAMETERS pa_key TYPE ${t}-${k} OBLIGATORY.`, `START-OF-SELECTION.\n  PERFORM build_range.\n  SELECT * FROM ${t} WHERE ${k} IN @gr_key INTO TABLE @gt_data.\n  WRITE / lines( gt_data ).`, `FORM build_range.\n  CLEAR gr_key.\n  CLEAR gs_range.\n  gs_range-sign = 'I'. gs_range-option = 'EQ'.\n  gs_range-low = pa_key.\n  APPEND gs_range TO gr_key.\nENDFORM.`);break;
 case 'form':
 guide('테이블 타입은 TOP에서 먼저 선언합니다. USING 입력 / CHANGING 출력으로 역할을 구분합니다.');
 report(`TYPES ty_t_company TYPE STANDARD TABLE OF t001 WITH DEFAULT KEY.\nDATA gt_company TYPE ty_t_company.\nPARAMETERS pa_bukrs TYPE t001-bukrs.`, `START-OF-SELECTION.\n  PERFORM get_company USING pa_bukrs CHANGING gt_company.\n  WRITE / lines( gt_company ).`, `FORM get_company USING pv_bukrs TYPE t001-bukrs\n                 CHANGING pt_company TYPE ty_t_company.\n  SELECT * FROM t001 INTO TABLE pt_company WHERE bukrs = pv_bukrs.\nENDFORM.`);break;
 case 'local-class':
 guide('로컬 클래스 이름은 LCL_을 사용하고 객체 참조는 선택한 GCL_/GO_ 접두사를 사용합니다. FORM은 화면 흐름, 클래스는 조회를 담당합니다.');
 report(`CLASS lcl_company DEFINITION.\n  PUBLIC SECTION.\n    METHODS get_text IMPORTING iv_bukrs TYPE t001-bukrs RETURNING VALUE(rv_text) TYPE t001-butxt.\nENDCLASS.\nCLASS lcl_company IMPLEMENTATION.\n  METHOD get_text.\n    SELECT SINGLE butxt FROM t001 INTO rv_text WHERE bukrs = iv_bukrs.\n  ENDMETHOD.\nENDCLASS.\nDATA gcl_company TYPE REF TO lcl_company.\nPARAMETERS pa_bukrs TYPE t001-bukrs.`, `START-OF-SELECTION.\n  PERFORM display_company.`, `FORM display_company.\n  DATA lv_text TYPE t001-butxt.\n  CREATE OBJECT gcl_company.\n  lv_text = gcl_company->get_text( pa_bukrs ).\n  WRITE / lv_text.\nENDFORM.`);break;
 case 'function':
 guide('SE37에서 Z 이름의 Function Group 및 Z_GET_COMPANY_TEXT를 생성하세요. Import IV_BUKRS TYPE BUKRS, Export EV_BUTXT TYPE BUTXT, Exception NOT_FOUND를 인터페이스 탭에 등록해야 합니다. 일반 리포트 Include에 FUNCTION을 붙이지 않습니다.');
 add('Z_GET_COMPANY_TEXT.abap',`FUNCTION z_get_company_text.\n  CLEAR ev_butxt.\n  SELECT SINGLE butxt FROM t001 INTO ev_butxt WHERE bukrs = iv_bukrs.\n  IF sy-subrc <> 0.\n    RAISE not_found.\n  ENDIF.\nENDFUNCTION.`,'SE37 · Function Module 소스');
 report(`PARAMETERS pa_bukrs TYPE t001-bukrs.\nDATA gv_text TYPE t001-butxt.`, `START-OF-SELECTION.\n  PERFORM call_company.`, `FORM call_company.\n  CALL FUNCTION 'Z_GET_COMPANY_TEXT'\n    EXPORTING iv_bukrs = pa_bukrs IMPORTING ev_butxt = gv_text\n    EXCEPTIONS not_found = 1 OTHERS = 2.\n  IF sy-subrc <> 0.\n    MESSAGE '회사코드를 찾지 못했습니다.' TYPE 'I'.\n    RETURN.\n  ENDIF.\n  WRITE / gv_text.\nENDFORM.`);break;
 case 'authority':
 guide('F_BKPF_BUK / ACTVT=03 예제입니다. SU21의 객체 필드와 실제 업무 ACTVT를 확인하세요. SU53으로 실패 원인을 확인합니다.');
 report(`PARAMETERS pa_bukrs TYPE t001-bukrs OBLIGATORY.`, `AT SELECTION-SCREEN.\n  PERFORM check_authority.\nSTART-OF-SELECTION.\n  WRITE / pa_bukrs.`, `FORM check_authority.\n  AUTHORITY-CHECK OBJECT 'F_BKPF_BUK'\n    ID 'BUKRS' FIELD pa_bukrs ID 'ACTVT' FIELD '03'.\n  IF sy-subrc <> 0.\n    MESSAGE '회사코드 조회 권한이 없습니다.' TYPE 'E'.\n  ENDIF.\nENDFORM.`);break;
 case 'upload': case 'download': {
 const upload=kind==='upload'; guide('SAP GUI 프런트엔드 전용입니다. 백그라운드/WebGUI에서 사용할 수 없습니다. UTF-8 한 줄 텍스트 형식이며 XLSX/CSV 파서가 아닙니다. 실제 금액·날짜 컬럼 변환은 별도 검증해야 합니다.');
 report(`PARAMETERS pa_file TYPE rlgrap-filename LOWER CASE OBLIGATORY.\nDATA: gt_lines TYPE STANDARD TABLE OF string, gv_file TYPE string.`, `START-OF-SELECTION.\n  PERFORM transfer_file.`, `FORM transfer_file.\n  IF sy-batch = 'X'.\n    MESSAGE 'SAP GUI에서 실행하세요.' TYPE 'I'.\n    RETURN.\n  ENDIF.\n  gv_file = pa_file.\n${upload?'':"  APPEND 'UTF-8 텍스트 예제' TO gt_lines.\n"}  CALL METHOD cl_gui_frontend_services=>gui_${upload?'upload':'download'}\n    EXPORTING filename = gv_file filetype = 'ASC' codepage = '4110'${upload?'':" confirm_overwrite = 'X'"}\n    CHANGING data_tab = gt_lines\n    EXCEPTIONS OTHERS = 1.\n  IF sy-subrc <> 0.\n    MESSAGE '파일 경로·권한·GUI 연결을 확인하세요.' TYPE 'I'.\n    RETURN.\n  ENDIF.\n  WRITE: / '줄 수', lines( gt_lines ).\nENDFORM.`);break;
 }
 case 'fi-check': return fi(o);
 case 'shdb': guide('실행 가능한 BDC 골격은 기존 BDC 실행 골격을 선택하세요. FB01/FBV1 화면은 릴리스·필드상태·세금·CO 조건에 따라 다릅니다. 임의 화면번호를 전표 완성 코드로 제공하지 않습니다.\n1. SHDB에서 대상 트랜잭션 1건 녹화\n2. 화면 시작 X / 필드명 / 값 / BDC_OKCODE 순서 보존\n3. 회사코드·날짜·통화와 CO 객체 값을 변수로 교체\n4. A모드, S업데이트로 테스트\n5. SY-SUBRC + BDCMSGCOLL의 A/E/X + 실제 문서번호 확인\n6. 성공/실패·재시도·중복 방지 및 LUW 설계');break;
 case 'lock': guide('SE11에서 사용자 테이블의 키를 포함하는 EZ* Lock Object를 만듭니다. 활성화하면 ENQUEUE_EZ* / DEQUEUE_EZ*가 생성됩니다. 이 객체의 실제 이름·클라이언트·키·_SCOPE 인터페이스는 SE37에서 확인해야 합니다.\n저장 흐름: 권한 확인 → ENQUEUE(FOREIGN_LOCK/SYSTEM_FAILURE 검사) → DB 재조회 및 검증 → INSERT/UPDATE/DELETE → COMMIT 또는 ROLLBACK → DEQUEUE.\n테이블을 잠그지 않은 SELECT 후 UPDATE만으로는 동시성 충돌을 방지하지 못합니다. CRUD 생성물은 이 잠금 객체 구현 이후 실무에 적용하세요.');break;
 default:throw Error('지원하지 않는 생성 유형입니다.');
 }
 return files;
}

function dynproF4(kind,o){
 const p=o.program.toLowerCase(),s=o.screen;
 const spec={
 'f4-account':{name:'account',type:'skb1-saknr',tab:'skb1',key:'saknr',context:'bukrs',ctxType:'t001-bukrs',label:'회사코드',condition:'bukrs = @gv_bukrs AND xloeb = @space AND xspeb = @space',convert:'ALPHA'},
 'f4-costcenter':{name:'costcenter',type:'csks-kostl',tab:'csks',key:'kostl',context:'kokrs',ctxType:'tka01-kokrs',label:'관리회계영역',condition:'kokrs = @gv_kokrs AND datab <= @sy-datum AND datbi >= @sy-datum',convert:'ALPHA'},
 'f4-order':{name:'order',type:'aufk-aufnr',tab:'aufk',key:'aufnr',context:'kokrs',ctxType:'tka01-kokrs',label:'관리회계영역',condition:'kokrs = @gv_kokrs AND loekz = @space',convert:'ALPHA'},
 'f4-wbs':{name:'wbs',type:'prps-posid',tab:'prps',key:'posid',context:'bukrs',ctxType:'t001-bukrs',label:'회사코드',condition:'pbukr = @gv_bukrs',convert:'ABPSN'},
 'f4-dynpro':{name:'key',type:`${o.table.toLowerCase()}-${o.key.toLowerCase()}`,tab:o.table.toLowerCase(),key:o.key.toLowerCase(),condition:'',convert:null}
 }[kind];
 const a=spec,field=(o.screenField||'GV_VALUE').toUpperCase(),v=field.toLowerCase(),ctx=a.context?`gv_${a.context}`:null;
 const condition=a.condition?`WHERE ${a.condition}`:'';
 const declaration=v.includes('-')?`DATA: BEGIN OF ${v.split('-')[0]}, ${v.split('-')[1]} TYPE ${a.type}, END OF ${v.split('-')[0]}.`:`DATA ${v} TYPE ${a.type}.`;
 const top=`${declaration}\nDATA: gv_okcode TYPE sy-ucomm${ctx?`,\n      ${ctx} TYPE ${a.ctxType}`:''}.\nCONSTANTS gc_screen TYPE sy-dynnr VALUE '${s}'.`;
 const readScreen=`  DATA: lt_dynp TYPE STANDARD TABLE OF dynpread, ls_dynp TYPE dynpread.\n${ctx?`  CLEAR ls_dynp. ls_dynp-fieldname = '${ctx.toUpperCase()}'. APPEND ls_dynp TO lt_dynp.\n`:''}  CLEAR ls_dynp. ls_dynp-fieldname = '${field}'. APPEND ls_dynp TO lt_dynp.\n  CALL FUNCTION 'DYNP_VALUES_READ'\n    EXPORTING dyname = sy-repid dynumb = gc_screen\n    TABLES dynpfields = lt_dynp EXCEPTIONS OTHERS = 1.\n  IF sy-subrc <> 0.\n    MESSAGE '화면 값을 읽지 못했습니다.' TYPE 'I'.\n    RETURN.\n  ENDIF.\n${ctx?`  READ TABLE lt_dynp INTO ls_dynp WITH KEY fieldname = '${ctx.toUpperCase()}'.\n  IF sy-subrc = 0. ${ctx} = ls_dynp-fieldvalue. ENDIF.\n  IF ${ctx} IS INITIAL.\n    MESSAGE '${a.label}을 먼저 입력하세요.' TYPE 'I'.\n    RETURN.\n  ENDIF.\n`:''}`;
 const conversion=a.convert?`  CALL FUNCTION 'CONVERSION_EXIT_${a.convert}_INPUT'\n    EXPORTING input = ${v} IMPORTING output = ${v}.\n`:'';
 const forms=`FORM f4_${a.name}.\n  DATA: lt_values TYPE STANDARD TABLE OF ${a.tab},\n        lt_return TYPE STANDARD TABLE OF ddshretval, ls_return TYPE ddshretval,\n        lt_update TYPE STANDARD TABLE OF dynpread, ls_update TYPE dynpread.\n${readScreen}  SELECT * FROM ${a.tab} ${condition}\n    ORDER BY PRIMARY KEY INTO TABLE @lt_values UP TO 500 ROWS.\n  IF lt_values IS INITIAL.\n    MESSAGE '조건에 맞는 후보가 없습니다.' TYPE 'I'.\n    RETURN.\n  ENDIF.\n  CALL FUNCTION 'F4IF_INT_TABLE_VALUE_REQUEST'\n    EXPORTING ddic_structure = '${a.tab.toUpperCase()}' retfield = '${a.key.toUpperCase()}'\n      value_org = 'S'\n    TABLES value_tab = lt_values return_tab = lt_return\n    EXCEPTIONS parameter_error = 1 no_values_found = 2 OTHERS = 3.\n  IF sy-subrc <> 0.\n    MESSAGE 'F4 호출에 실패했습니다.' TYPE 'I'.\n    RETURN.\n  ENDIF.\n  READ TABLE lt_return INTO ls_return INDEX 1.\n  IF sy-subrc <> 0 OR ls_return-fieldval IS INITIAL. RETURN. ENDIF.\n  ${v} = ls_return-fieldval.\n${conversion}  CLEAR ls_update.\n  ls_update-fieldname = '${field}'. ls_update-fieldvalue = ls_return-fieldval.\n  APPEND ls_update TO lt_update.\n  CALL FUNCTION 'DYNP_VALUES_UPDATE'\n    EXPORTING dyname = sy-repid dynumb = gc_screen\n    TABLES dynpfields = lt_update EXCEPTIONS OTHERS = 1.\n  IF sy-subrc <> 0.\n    MESSAGE '화면 필드 반영에 실패했습니다.' TYPE 'I'.\n  ENDIF.\nENDFORM.\n\nFORM check_${a.name}.\n  DATA lv_found TYPE ${a.type}.\n  IF ${v} IS INITIAL${ctx?` OR ${ctx} IS INITIAL`:''}.\n    MESSAGE '필수 입력값을 확인하세요.' TYPE 'E'.\n  ENDIF.\n${conversion}  SELECT SINGLE ${a.key} FROM ${a.tab}\n    WHERE ${a.key} = @${v}${a.condition?' AND '+a.condition:''} INTO @lv_found.\n  IF sy-subrc <> 0.\n    MESSAGE '입력값 또는 기준 조직·유효기간을 확인하세요.' TYPE 'E'.\n  ENDIF.\nENDFORM.`;
 return [f('00_README.txt',`Standard ABAP 7.40 SP08+ / SAP GUI Dynpro 전용.\n1. SE38 실행 프로그램 및 TOP/O01/I01/F01 Include 생성\n2. SE51 일반 화면 ${s}, 다음 화면 ${s}, OK Code GV_OKCODE\n3. 화면 필드 ${field}는 프로그램 필드 ${a.type}를 참조${ctx?`; ${ctx.toUpperCase()}는 ${a.ctxType} 참조`:''}\n4. SE41 S${s}: BACK/EXIT/CANC 기능 유형 E. 화면 입력 필드에 F4 표시.\n5. 새 Z DDIC는 필요 없음. 표준 ${a.tab.toUpperCase()} 및 DYNPREAD/DDSHRETVAL 사용.\n6. POV는 PAI 이전이라 DYNP_VALUES_READ로 아직 전송되지 않은 조직값을 읽음. 취소 시 기존 값 유지. 선택값은 프로그램 변수와 화면 버퍼에 반영. Enter는 CHAIN으로 재검증.\n7. 후보는 최대 500건: 많은 데이터는 DDIC Search Help 또는 검색조건을 추가하세요.\n8. 이 후보 목록은 F4IF 표준 FM 기반 사용자 도움말이며 모든 표준 업무 검증을 대신하지 않습니다. 계정: SKA1 전역 차단/삭제·전기 가능 여부, 코스트센터: 잠금, 내부오더/WBS: JEST 상태·권한 등을 저장 시 추가 검사하세요. WBS는 POSID에 ABPSN 변환을 적용하며 PSPNR(ABPSP)과 혼동하지 마세요. 근거: https://userapps.support.sap.com/sap/support/knowledge/en/3558515\nSAP 컴파일·실행 미검증.`, '전제 · SE11 / SE51 / SE41 설정'),
 f(p+'.abap',`REPORT ${p}.\nINCLUDE ${p}_top.\nSTART-OF-SELECTION.\n  CALL SCREEN gc_screen.\nINCLUDE ${p}_o01.\nINCLUDE ${p}_i01.\nINCLUDE ${p}_f01.`,'SE38 · 실행 프로그램'),f(p+'_top.abap',top,'SE38 · TOP'),
 f(p+'_o01.abap',`MODULE status_${s} OUTPUT.\n  SET PF-STATUS 'S${s}'.\nENDMODULE.`,'SE38 · O01'),
 f(p+'_i01.abap',`MODULE exit_${s} INPUT.\n  CLEAR gv_okcode.\n  LEAVE TO SCREEN 0.\nENDMODULE.\nMODULE f4_${a.name} INPUT.\n  PERFORM f4_${a.name}.\nENDMODULE.\nMODULE check_${a.name} INPUT.\n  PERFORM check_${a.name}.\nENDMODULE.\nMODULE command_${s} INPUT.\n  CLEAR gv_okcode.\nENDMODULE.`,'SE38 · I01'),f(p+'_f01.abap',forms,'SE38 · F01'),
 f('screen_'+s+'.flow.abap',`PROCESS BEFORE OUTPUT.\n  MODULE status_${s}.\nPROCESS AFTER INPUT.\n  MODULE exit_${s} AT EXIT-COMMAND.\n  CHAIN.\n${ctx?`    FIELD ${ctx}.\n`:''}    FIELD ${v}.\n    MODULE check_${a.name}.\n  ENDCHAIN.\n  MODULE command_${s}.\nPROCESS ON VALUE-REQUEST.\n  FIELD ${v} MODULE f4_${a.name}.`,'SE51 · Flow Logic')];
}

function crud(kind,o){
 const p=o.program.toLowerCase(),t=o.table.toLowerCase(),k=o.key.toLowerCase();
 if(!/^[zy]/i.test(t))throw Error('DB 변경은 사용자 Z/Y 테이블만 지원합니다. 예: ZWB_DEMO / ID. SE11 계약을 먼저 확인하세요.');
 const op={'db-create':'C','db-update':'U','db-delete':'D',crud:'R'}[kind];
 return [f('00_README.txt',`Standard ABAP 7.40 SP08+. SE11에 ${t.toUpperCase()} 투명 테이블을 먼저 만드세요.\n필수 필드: MANDT(CLNT, 키), ${k.toUpperCase()}(CHAR10, 키), DESCRIPTION(CHAR80). ${k.toUpperCase()}가 유일한 업무키인 예제입니다.\n조회 R / 생성 C / 수정 U / 삭제 D. 수정·삭제는 영향 행 수를 검사합니다. 기본값은 조회이며 쓰기는 PA_APPLY 체크 시에만 수행합니다.\n공용 운영에는 생성된 잠금 객체와 업무 권한을 추가하세요. 이 예제는 단독 데모 테이블용이며 표준 SAP 테이블에 적용하지 마세요.\nCOMMIT/ROLLBACK은 호출 최상위에서 소유합니다. DB 예외는 ROLLBACK합니다. SAP 실행 미검증.`, 'SE11 계약 · 동시성 전제'),
 f(p+'.abap',`REPORT ${p}.\nINCLUDE ${p}_top.\nAT SELECTION-SCREEN.\n  IF pa_op CN 'CRUD' OR pa_op IS INITIAL.\n    MESSAGE 'C/R/U/D 중 하나를 입력하세요.' TYPE 'E'.\n  ENDIF.\nSTART-OF-SELECTION.\n  PERFORM maintain_data.\nINCLUDE ${p}_f01.`,'SE38 · 실행 프로그램'),
 f(p+'_top.abap',`PARAMETERS: pa_id TYPE ${t}-${k} OBLIGATORY,\n pa_text TYPE ${t}-description LOWER CASE,\n pa_op TYPE c LENGTH 1 DEFAULT '${op}', pa_apply AS CHECKBOX.\nDATA: gs_data TYPE ${t}, gv_subrc TYPE sy-subrc, gv_count TYPE sy-dbcnt.`,'SE38 · TOP'),
 f(p+'_f01.abap',`FORM maintain_data.\n  DATA lx_sql TYPE REF TO cx_sy_open_sql_db.\n  IF pa_op = 'R'.\n    SELECT SINGLE * FROM ${t} WHERE ${k} = @pa_id INTO @gs_data.\n    IF sy-subrc = 0.\n      WRITE: / gs_data-${k}, gs_data-description.\n    ELSE.\n      MESSAGE '데이터가 없습니다.' TYPE 'I'.\n    ENDIF.\n    RETURN.\n  ENDIF.\n  IF pa_apply IS INITIAL.\n    MESSAGE '쓰기 적용 체크 후 실행하세요.' TYPE 'I'.\n    RETURN.\n  ENDIF.\n  TRY.\n      CASE pa_op.\n        WHEN 'C'.\n          CLEAR gs_data.\n          gs_data-mandt = sy-mandt.\n          gs_data-${k} = pa_id. gs_data-description = pa_text.\n          INSERT ${t} FROM @gs_data.\n        WHEN 'U'.\n          UPDATE ${t} SET description = @pa_text WHERE ${k} = @pa_id.\n        WHEN 'D'.\n          DELETE FROM ${t} WHERE ${k} = @pa_id.\n      ENDCASE.\n      gv_subrc = sy-subrc. gv_count = sy-dbcnt.\n      IF gv_subrc = 0 AND gv_count = 1.\n        COMMIT WORK AND WAIT.\n        WRITE / '처리되었습니다.'.\n      ELSE.\n        ROLLBACK WORK.\n        MESSAGE '중복 키 또는 대상 없음: 변경하지 않았습니다.' TYPE 'I'.\n      ENDIF.\n    CATCH cx_sy_open_sql_db INTO lx_sql.\n      ROLLBACK WORK.\n      MESSAGE lx_sql->get_text( ) TYPE 'I'.\n  ENDTRY.\nENDFORM.`,'SE38 · F01')];
}

function grid(kind,o){
 const p=o.program.toLowerCase(),s=o.screen,t=o.table.toLowerCase(),k=o.key.toLowerCase(),ctrl=(o.container||'CC_ALV').toUpperCase();
 const toolbar=kind==='alv-toolbar',top=kind==='alv-top',edit=kind==='alv-edit',hot=kind==='alv-hotspot';
 const definitions=toolbar?`METHODS on_toolbar FOR EVENT toolbar OF cl_gui_alv_grid IMPORTING e_object e_interactive.\n    METHODS on_command FOR EVENT user_command OF cl_gui_alv_grid IMPORTING e_ucomm.`:top?`METHODS on_top FOR EVENT top_of_page OF cl_gui_alv_grid IMPORTING e_dyndoc_id table_index.`:edit?`METHODS on_changed FOR EVENT data_changed OF cl_gui_alv_grid IMPORTING er_data_changed.`:hot?`METHODS on_hotspot FOR EVENT hotspot_click OF cl_gui_alv_grid IMPORTING e_row_id e_column_id es_row_no.\n    METHODS on_double FOR EVENT double_click OF cl_gui_alv_grid IMPORTING e_row e_column es_row_no.`:'';
 const methods=toolbar?`METHOD on_toolbar.\n    DATA ls_button TYPE stb_button.\n    ls_button-function = 'ZREFRESH'. ls_button-text = '새로고침'.\n    APPEND ls_button TO e_object->mt_toolbar.\n  ENDMETHOD.\n  METHOD on_command.\n    IF e_ucomm = 'ZREFRESH'.\n      PERFORM get_data. PERFORM refresh_grid.\n    ENDIF.\n  ENDMETHOD.`:top?`METHOD on_top.\n    CALL METHOD e_dyndoc_id->add_text EXPORTING text = '조회 결과 요약'.\n    CALL METHOD e_dyndoc_id->new_line.\n    CALL METHOD e_dyndoc_id->add_text EXPORTING text = '최대 500건 · 조회 조건을 확인하세요.'.\n  ENDMETHOD.`:edit?`METHOD on_changed.\n    DATA ls_cell TYPE lvc_s_modi.\n    LOOP AT er_data_changed->mt_good_cells INTO ls_cell.\n      IF ls_cell-fieldname = '${k.toUpperCase()}' AND ls_cell-value IS INITIAL.\n        CALL METHOD er_data_changed->add_protocol_entry\n          EXPORTING i_msgid = '00' i_msgno = '001' i_msgty = 'E'\n                    i_msgv1 = '키 값은 필수입니다.'\n                    i_fieldname = ls_cell-fieldname i_row_id = ls_cell-row_id.\n      ENDIF.\n    ENDLOOP.\n  ENDMETHOD.`:hot?`METHOD on_hotspot.\n    DATA ls_data TYPE ${t}.\n    READ TABLE gt_data INTO ls_data INDEX es_row_no-row_id.\n    IF sy-subrc = 0. MESSAGE '행이 선택되었습니다.' TYPE 'S'. ENDIF.\n  ENDMETHOD.\n  METHOD on_double.\n    DATA ls_data TYPE ${t}.\n    READ TABLE gt_data INTO ls_data INDEX es_row_no-row_id.\n    IF sy-subrc = 0. MESSAGE '행이 더블클릭되었습니다.' TYPE 'S'. ENDIF.\n  ENDMETHOD.`:'';
 const events=toolbar?`SET HANDLER gcl_events->on_toolbar gcl_events->on_command FOR gcl_grid.`:top?`SET HANDLER gcl_events->on_top FOR gcl_grid.`:edit?`SET HANDLER gcl_events->on_changed FOR gcl_grid.\n    gcl_grid->register_edit_event( i_event_id = cl_gui_alv_grid=>mc_evt_modified ).\n    gcl_grid->register_edit_event( i_event_id = cl_gui_alv_grid=>mc_evt_enter ).`:hot?`SET HANDLER gcl_events->on_hotspot gcl_events->on_double FOR gcl_grid.`:'';
 return [f('00_README.txt',`Standard ABAP 7.40 SP08+ / SAP GUI.\nSE11: ${o.table.toUpperCase()}의 활성 DDIC 구조와 실제 필드 ${o.key.toUpperCase()} 확인.\nSE51 화면 ${s}, 다음 화면 ${s}, OK Code GV_OKCODE. Custom Control ${ctrl} 생성${top?' 및 CC_HEADER(상단 요약용) 추가':''}.\nSE41 S${s}: BACK/EXIT/CANC 기능유형 E${edit?', CHECK 일반기능(저장 전 검사 시연)':''}.\nSE38 실행 프로그램과 TOP/C01/O01/I01/F01 Include를 생성. MAKE_FCAT → SET_TABLE_FOR_FIRST_DISPLAY 연결 완료.\n${top?'Grid TOP_OF_PAGE는 리스트 이벤트가 아닙니다. CL_DD_DOCUMENT와 별도 컨테이너에서 LIST_PROCESSING_EVENTS 및 DISPLAY_DOCUMENT로 표시합니다.':''}\n${edit?'CHECK_CHANGED_DATA로 편집 버퍼를 반영한 후 검증합니다. 예제는 메모리 편집이며 DB 저장은 하지 않습니다. 키 수정은 실무 데이터 모델에 맞춰 제한하세요.':''}\n실행 순서: F8 → 표시 → 이벤트 → F3. SAP 실행 미검증.`, '설정 및 적용 순서'),
 f(p+'.abap',`REPORT ${p}.\nINCLUDE ${p}_top.\nINCLUDE ${p}_c01.\nSTART-OF-SELECTION.\n  PERFORM get_data.\n  CALL SCREEN '${s}'.\nINCLUDE ${p}_o01.\nINCLUDE ${p}_i01.\nINCLUDE ${p}_f01.`,'SE38 · 실행 프로그램'),
 f(p+'_top.abap',`DATA: gt_data TYPE STANDARD TABLE OF ${t}, gs_data TYPE ${t},\n      gt_fcat TYPE lvc_t_fcat, gs_fcat TYPE lvc_s_fcat,\n      gs_layout TYPE lvc_s_layo, gs_stable TYPE lvc_s_stbl, gv_okcode TYPE sy-ucomm.\nDATA: gcl_container TYPE REF TO cl_gui_custom_container,\n      gcl_grid TYPE REF TO cl_gui_alv_grid.\n${top?'DATA: gcl_header TYPE REF TO cl_gui_custom_container,\n      gcl_document TYPE REF TO cl_dd_document.':''}\n${definitions?'CLASS lcl_events DEFINITION DEFERRED.\nDATA gcl_events TYPE REF TO lcl_events.':''}`, 'SE38 · TOP'),
 f(p+'_c01.abap',definitions?`CLASS lcl_events DEFINITION.\n  PUBLIC SECTION.\n    ${definitions}\nENDCLASS.\nCLASS lcl_events IMPLEMENTATION.\n  ${methods}\nENDCLASS.`:'* 이 유형은 이벤트 클래스가 필요 없습니다.', 'SE38 · C01'),
 f(p+'_o01.abap',`MODULE status_${s} OUTPUT.\n  SET PF-STATUS 'S${s}'.\n  IF gcl_grid IS NOT BOUND.\n    PERFORM display_grid.\n  ENDIF.\nENDMODULE.`,'SE38 · O01'),
 f(p+'_i01.abap',`MODULE exit_${s} INPUT.\n  IF gcl_grid IS BOUND. gcl_grid->free( ). ENDIF.\n  IF gcl_container IS BOUND. gcl_container->free( ). ENDIF.\n${top?'  IF gcl_header IS BOUND. gcl_header->free( ). ENDIF.\n  CLEAR: gcl_header, gcl_document.\n':''}  CLEAR: gcl_grid, gcl_container${definitions?', gcl_events':''}, gv_okcode.\n  LEAVE TO SCREEN 0.\nENDMODULE.\nMODULE command_${s} INPUT.\n${edit?`  DATA lv_valid TYPE c LENGTH 1.\n  IF gv_okcode = 'CHECK'.\n    gcl_grid->check_changed_data( IMPORTING e_valid = lv_valid ).\n    IF lv_valid IS INITIAL.\n      CLEAR gv_okcode. RETURN.\n    ENDIF.\n    MESSAGE '입력 검사 완료. DB 저장 전 업무 검증을 추가하세요.' TYPE 'S'.\n  ENDIF.\n`:''}  CLEAR gv_okcode.\nENDMODULE.`,'SE38 · I01'),
 f(p+'_f01.abap',`FORM get_data.\n  SELECT * FROM ${t} ORDER BY PRIMARY KEY INTO TABLE @gt_data UP TO 500 ROWS.\nENDFORM.\nFORM make_fcat.\n  CLEAR: gt_fcat, gs_fcat.\n  CALL FUNCTION 'LVC_FIELDCATALOG_MERGE'\n    EXPORTING i_structure_name = '${o.table.toUpperCase()}'\n    CHANGING ct_fieldcat = gt_fcat\n    EXCEPTIONS inconsistent_interface = 1 program_error = 2 OTHERS = 3.\n  IF sy-subrc <> 0.\n    MESSAGE 'DDIC 필드 카탈로그 생성 실패' TYPE 'A'.\n  ENDIF.\n  LOOP AT gt_fcat INTO gs_fcat.\n    IF gs_fcat-fieldname = '${k.toUpperCase()}'.\n      gs_fcat-col_pos = 1.\n${hot?"      gs_fcat-hotspot = 'X'.\n":''}${edit?"      gs_fcat-edit = 'X'.\n":''}      MODIFY gt_fcat FROM gs_fcat.\n    ENDIF.\n  ENDLOOP.\nENDFORM.\nFORM display_grid.\n  PERFORM make_fcat.\n  CREATE OBJECT gcl_container EXPORTING container_name = '${ctrl}'.\n  CREATE OBJECT gcl_grid EXPORTING i_parent = gcl_container.\n${definitions?'  CREATE OBJECT gcl_events.\n  '+events+'\n':''}  gs_layout-zebra = 'X'. gs_layout-cwidth_opt = 'X'.\n  CALL METHOD gcl_grid->set_table_for_first_display\n    EXPORTING is_layout = gs_layout\n    CHANGING it_outtab = gt_data it_fieldcatalog = gt_fcat\n    EXCEPTIONS invalid_parameter_combination = 1 program_error = 2 too_many_lines = 3 OTHERS = 4.\n  IF sy-subrc <> 0. MESSAGE 'ALV 표시 실패' TYPE 'A'. ENDIF.\n${top?`  CREATE OBJECT gcl_header EXPORTING container_name = 'CC_HEADER'.\n  CREATE OBJECT gcl_document EXPORTING style = 'ALV_GRID'.\n  gcl_document->initialize_document( ).\n  CALL METHOD gcl_grid->list_processing_events\n    EXPORTING i_event_name = 'TOP_OF_PAGE' i_dyndoc_id = gcl_document.\n  CALL METHOD gcl_document->display_document\n    EXPORTING parent = gcl_header\n    EXCEPTIONS html_display_error = 1 OTHERS = 2.\n  IF sy-subrc <> 0. MESSAGE '상단 요약 표시 실패' TYPE 'I'. ENDIF.\n`:''}ENDFORM.\nFORM refresh_grid.\n  gs_stable-row = 'X'. gs_stable-col = 'X'.\n  gcl_grid->refresh_table_display( is_stable = gs_stable ).\nENDFORM.`,'SE38 · F01'),
 f('screen_'+s+'.flow.abap',`PROCESS BEFORE OUTPUT.\n  MODULE status_${s}.\nPROCESS AFTER INPUT.\n  MODULE exit_${s} AT EXIT-COMMAND.\n  MODULE command_${s}.`,'SE51 · Flow Logic')];
}

function fi(o){const p=o.program.toLowerCase();return [
 f('00_README.txt','Standard ABAP / FI BAPI_ACC_DOCUMENT_CHECK 준비 예제. BAPIAC* DDIC와 BAPI 존재 여부를 SE37에서 확인하세요. 전기 코드는 포함하지 않습니다. PA_GL1/2는 실제 회사코드 G/L 계정, PA_AMT는 양수 내부 금액입니다. 차변 +, 대변 - 로 균형을 맞춥니다. 세금·CO·필드상태·전기기간·권한 검사는 회사별로 다릅니다. 이 간단한 2개 G/L 항목이 모든 계정에서 통과한다는 의미는 아닙니다. BAPI RETURN의 A/E/X를 실패로 판정합니다. BAPI CHECK는 잠금·중복방지·POST를 대체하지 않습니다. SAP 실행 미검증.','FI 적용 조건'),
 f(p+'.abap',`REPORT ${p}.\nPARAMETERS: pa_bukrs TYPE t001-bukrs OBLIGATORY,\n pa_gl1 TYPE skb1-saknr OBLIGATORY, pa_gl2 TYPE skb1-saknr OBLIGATORY,\n pa_curr TYPE tcurc-waers DEFAULT 'KRW', pa_amt TYPE bapiaccr09-amt_doccur OBLIGATORY.\nDATA: gs_header TYPE bapiache09, gt_gl TYPE STANDARD TABLE OF bapiacgl09,\n gs_gl TYPE bapiacgl09, gt_amount TYPE STANDARD TABLE OF bapiaccr09,\n gs_amount TYPE bapiaccr09, gt_return TYPE STANDARD TABLE OF bapiret2,\n gs_return TYPE bapiret2, gv_error TYPE abap_bool.\nAT SELECTION-SCREEN.\n  IF pa_amt <= 0. MESSAGE '금액은 양수로 입력하세요.' TYPE 'E'. ENDIF.\nSTART-OF-SELECTION.\n  PERFORM check_document.\nFORM check_document.\n  CLEAR: gs_header, gt_gl, gt_amount, gt_return, gv_error.\n  gs_header-username = sy-uname. gs_header-comp_code = pa_bukrs.\n  gs_header-doc_date = sy-datum. gs_header-pstng_date = sy-datum.\n  gs_header-doc_type = 'SA'. gs_header-bus_act = 'RFBU'.\n  CLEAR gs_gl. gs_gl-itemno_acc = '0000000001'. gs_gl-gl_account = pa_gl1.\n  gs_gl-comp_code = pa_bukrs. APPEND gs_gl TO gt_gl.\n  gs_gl-itemno_acc = '0000000002'. gs_gl-gl_account = pa_gl2. APPEND gs_gl TO gt_gl.\n  CLEAR gs_amount. gs_amount-itemno_acc = '0000000001'.\n  gs_amount-currency = pa_curr. gs_amount-amt_doccur = pa_amt.\n  APPEND gs_amount TO gt_amount.\n  gs_amount-itemno_acc = '0000000002'. gs_amount-amt_doccur = 0 - pa_amt.\n  APPEND gs_amount TO gt_amount.\n  CALL FUNCTION 'BAPI_ACC_DOCUMENT_CHECK'\n    EXPORTING documentheader = gs_header\n    TABLES accountgl = gt_gl currencyamount = gt_amount return = gt_return.\n  LOOP AT gt_return INTO gs_return.\n    WRITE: / gs_return-type, gs_return-id, gs_return-number, gs_return-message.\n    IF gs_return-type CA 'AEX'. gv_error = abap_true. ENDIF.\n  ENDLOOP.\n  IF gv_error IS INITIAL. WRITE / 'CHECK 통과: 전기는 수행하지 않았습니다.'. ENDIF.\nENDFORM.`,'SE38 · 실행 프로그램')];}
